const state = $getWorkflowStaticData('global');
return [{ json: {
  updatedAfter: state.chemicalV2UpdatedAfter ?? '1970-01-01T00:00:00.000Z',
} }];

const response = $('Lấy phiếu vật tư hóa chất').first().json;
if (response.meta?.hasMore) {
  throw new Error('API còn trang dữ liệu; chưa cập nhật watermark để tránh bỏ sót');
}
if (response.meta?.layout !== 'vh1_v2') {
  throw new Error('API chưa trả đúng bố cục vh1_v2; hãy build website mới trước khi chạy');
}
if (response.meta?.syncScope !== 'chemicals') {
  throw new Error('API chưa trả đúng phạm vi chemicals');
}
const changes = Array.isArray(response.data) ? response.data : [];
const deletedKeys = new Set(
  (Array.isArray(response.meta?.deletedSyncKeys) ? response.meta.deletedSyncKeys : [])
    .map((key) => String(key ?? '').trim())
    .filter(Boolean)
);
const keyRows = Array.isArray($json.values) ? $json.values : [];
const metadata = $('Đọc metadata Sheet hóa chất').first().json;
const sheet = (Array.isArray(metadata.sheets) ? metadata.sheets : [])
  .find((entry) => entry?.properties?.title === 'VH1_HOACHAT_DONGBO');
const sheetId = sheet?.properties?.sheetId;
if (!Number.isInteger(sheetId)) throw new Error('Không tìm thấy sheetId của VH1_HOACHAT_DONGBO');

const originalRowByKey = new Map();
for (let index = 0; index < keyRows.length; index++) {
  const key = String(keyRows[index]?.[0] ?? '').trim();
  if (key && !originalRowByKey.has(key)) originalRowByKey.set(key, index + 3);
}
const deletedRows = Array.from(deletedKeys)
  .map((key) => originalRowByKey.get(key))
  .filter((row) => Number.isInteger(row))
  .sort((a, b) => b - a);
const deletedBefore = (rowNumber) => deletedRows.reduce(
  (count, deletedRow) => count + Number(deletedRow < rowNumber),
  0
);

const rowByKey = new Map();
for (const [key, originalRow] of originalRowByKey.entries()) {
  if (deletedKeys.has(key)) continue;
  rowByKey.set(key, originalRow - deletedBefore(originalRow));
}
let nextRow = keyRows.length + 3 - deletedRows.length;
const columns = 'ABCDEFGHIJKLMNOPQRSTU'.split('');
const formatDateTime = (value) => new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Ho_Chi_Minh',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23',
}).format(value).replace(',', '');
const syncedAt = formatDateTime(new Date());
const requests = deletedRows.map((rowNumber) => ({
  deleteDimension: {
    range: {
      sheetId,
      dimension: 'ROWS',
      startIndex: rowNumber - 1,
      endIndex: rowNumber,
    },
  },
}));

for (const change of changes) {
  const key = String(change.syncKey ?? change.row?.R ?? '').trim();
  if (!key) throw new Error('Dòng hóa chất thiếu SYNC_KEY');
  if (deletedKeys.has(key)) continue;
  let rowNumber = rowByKey.get(key);
  if (!rowNumber) {
    rowNumber = nextRow++;
    rowByKey.set(key, rowNumber);
  }
  const values = columns.map((column) => {
    if (column === 'U') return syncedAt;
    const value = change.row?.[column];
    return value === null || value === undefined ? '' : value;
  });
  requests.push({
    updateCells: {
      start: { sheetId, rowIndex: rowNumber - 1, columnIndex: 0 },
      rows: [{
        values: values.map((value) => ({
          userEnteredValue: value === ''
            ? {}
            : typeof value === 'number'
              ? { numberValue: value }
              : typeof value === 'boolean'
                ? { boolValue: value }
                : { stringValue: String(value) },
        })),
      }],
      fields: 'userEnteredValue',
    },
  });
}

if (requests.length === 0) {
  // Tombstone không còn dòng tương ứng (ví dụ phiếu bị xóa trước lần sync đầu).
  // Ghi lại đúng tiêu đề R2 như một no-op để batchUpdate vẫn thành công và được phép lưu watermark.
  requests.push({
    updateCells: {
      start: { sheetId, rowIndex: 1, columnIndex: 17 },
      rows: [{ values: [{ userEnteredValue: { stringValue: 'SYNC_KEY' } }] }],
      fields: 'userEnteredValue',
    },
  });
}

return [{ json: {
  requests,
  watermark: response.meta?.watermark,
  syncedRows: changes.length,
  deletedRows: deletedRows.length,
  missingDeletedKeys: deletedKeys.size - deletedRows.length,
} }];

const plan = $('Lập kế hoạch upsert hóa chất').first().json;
if (!plan.watermark) throw new Error('Thiếu watermark sau khi ghi Sheet V2');
const state = $getWorkflowStaticData('global');
state.chemicalV2UpdatedAfter = plan.watermark;
return [{ json: {
  success: true,
  syncedRows: plan.syncedRows,
  deletedRows: plan.deletedRows,
  missingDeletedKeys: plan.missingDeletedKeys,
  watermark: plan.watermark,
  targetSheet: 'VH1_HOACHAT_DONGBO',
} }];

const response = $('Lấy phiếu vật tư hóa chất').first().json;
if (response.meta?.hasMore) throw new Error('API còn trang dữ liệu');
if (response.meta?.layout !== 'vh1_v2') throw new Error('API chưa trả đúng bố cục vh1_v2');
if (response.meta?.syncScope !== 'chemicals') throw new Error('API chưa trả đúng phạm vi chemicals');
if (!response.meta?.watermark) throw new Error('Thiếu watermark từ API');
const state = $getWorkflowStaticData('global');
state.chemicalV2UpdatedAfter = response.meta.watermark;
return [{ json: {
  success: true,
  syncedRows: 0,
  watermark: response.meta.watermark,
  targetSheet: 'VH1_HOACHAT_DONGBO',
} }];
